if(b.dataset.choice!==undefined){const previousHealth=G.health;const result=E.resolveEvent(G,Number(b.dataset.choice));actionAudio.play(result.ok?'choice':'error',{hurt:G.health<previousHealth});if(G.ended)actionAudio.play(G.won?'win':'lose');modalMode='';closeModal();save();render();toast(result.message);if(G.ended)showEnd();return;}
if(b.dataset.use){const id=b.dataset.use;if(D.items[id].risk)openModal('ยอมรับความเสี่ยงนี้หรือไม่?',`<p>${D.items[id].name}: ${D.items[id].desc}</p><div class="modal-actions"><button class="button quiet" data-close>กลับไปเตรียมให้สะอาด</button><button class="button danger" data-risk-use="${id}">ใช้ทั้งอย่างนี้</button></div>`);else run('consume',id);return;}
if(b.dataset.riskUse){closeModal();return run('consume',b.dataset.riskUse);}
