if(b.hasAttribute('data-transfer-confirm')){const id=$('modalBody').querySelector('[data-transfer-item]').dataset.transferItem,type=$('transferType').value,quantity=Number($('transferQuantity').value),plan=E.inventoryPlan(G,type,id,quantity);if(!plan.ok)return toast(plan.message);closeModal();return run(type,id,quantity);}
