if(b.dataset.confirmDismantle){closeModal();return run('dismantle',b.dataset.confirmDismantle);}
if(b.hasAttribute('data-newgame'))return newGameDialog();
if(b.dataset.difficulty){G=E.newGame(b.dataset.difficulty);tab='gather';mapSelected='clearing';save();closeModal();render();toast('การเดินทางครั้งใหม่เริ่มขึ้นแล้ว');return;}
if(b.hasAttribute('data-end-journal')){closeModal();return setTab('journal');}
 if(b.dataset.slotSave){const n=Number(b.dataset.slotSave),existing=readSlot(n);if(existing){openModal(`บันทึกทับช่อง ${n}?`,`<p>${existing.invalid?'ช่องนี้มีข้อมูลที่อ่านไม่ได้ การบันทึกทับจะลบข้อมูลเดิม':`ช่องนี้มีเซฟวันที่ ${existing.day} เวลา ${time(existing.time)} ที่${E.site(existing).name}`}</p><p>ความคืบหน้าในช่องเดิมจะถูกแทนที่ด้วยสถานะปัจจุบัน</p><div class="modal-actions"><button class="button quiet" data-close>ยกเลิก</button><button class="button primary" data-confirm-slot-save="${n}">${icon('save')}บันทึกทับ</button></div>`,'slot-confirm','SAVE SLOT');}else writeSlot(n);return;}
