if(b.dataset.slotLoad){const n=Number(b.dataset.slotLoad),loaded=readSlot(n);if(!loaded||loaded.invalid)return toast(loaded?.error||'ช่องนี้ยังว่าง');openModal(`โหลดช่อง ${n}?`,`<p>วันที่ ${loaded.day} เวลา ${time(loaded.time)} ที่${E.site(loaded).name}</p><p>ความคืบหน้าปัจจุบันจะถูกแทนที่</p><div class="modal-actions"><button class="button quiet" data-close>ยกเลิก</button><button class="button primary" data-confirm-slot-load="${n}">${icon('save')}โหลดเซฟนี้</button></div>`,'slot-confirm','LOAD SLOT');return;}
